class Solution {
    public int unequalTriplets(int[] nums){
        Arrays.sort(nums);
        int answer=0,n=nums.length;
        for(int i=0;i<n;){
            int j=i+1;
            while(j<n&&nums[j]==nums[i])j++;
            answer+=i*(j-i)*(n-j);
            i=j;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun unequalTriplets(nums:IntArray):Int{
        nums.sort();
        var answer=0;
        var i=0;
        while(i<nums.size){
            var j=i+1;
            while(j<nums.size&&nums[j]==nums[i])j++;
            answer+=i*(j-i)*(nums.size-j);
            i=j
        };
        return answer
    }
}

